gh api graphql -f query=
{
  repository(owner: "vercel", name: "next.js") {
    pullRequests(first: 10, states: MERGED, labels: ["Pages Router"], orderBy: {field: UPDATED_AT, direction: DESC}) {
      totalCount
      nodes {
        number
        title
        mergedAt
      }
    }
  }
}

